const d = $input.item.json;
const creds = d.userCredentials || {};
return { json: { ...d, status: 'Posting', timestamp: new Date().toISOString(), _fb: creds.facebook || null, _ig: creds.instagram || null, _li: creds.linkedin || null, _gmail: creds.gmail || null, _tiktok: creds.tiktok || null, _eventbrite: creds.eventbrite || null, _luma: creds.luma || null, _meetup: creds.meetup || null } };

const d = $input.item.json;
if (d.imageUrl && d.imageUrl.trim() !== '') {
  return { json: { ...d, _skipImageGen: true } };
}
const name = (d.name || '').trim();
const desc = (d.description || '').substring(0, 200).trim();
const loc = (d.location || '').trim();
const time = (d.time || '').trim();
const email = (d.contactEmail || '').trim();
const type = d.campaignType || 'event';
let dateStr = '';
if (d.date) {
  try {
    const dt = new Date(d.date + 'T00:00:00');
    dateStr = dt.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
  } catch(_) { dateStr = d.date; }
}
const pts = [dateStr ? 'Date: ' + dateStr : null, time ? 'Time: ' + time : null, loc ? 'Venue: ' + loc : null, email ? 'Contact: ' + email : null].filter(Boolean);
const prompt = 'Create a stunning professional ' + type + ' marketing poster. Title: "' + name + '". ' + (desc ? 'About: ' + desc + '. ' : '') + pts.join('. ') + ' Design: dark premium background with deep purple and electric blue gradient, event title in very large bold white text at top, all event details clearly listed in clean white text, modern corporate conference poster style, EVOKE CMO branding at bottom, 1:1 square format.';
return { json: { ...d, _skipImageGen: false, _geminiPrompt: prompt } };

const d = $input.item.json;
const orig = $('Build Gemini Prompt').first().json;
const parts = d.candidates?.[0]?.content?.parts || [];
const imgPart = parts.find(p => p.inlineData && p.inlineData.data);
const base64Image = imgPart ? imgPart.inlineData.data : null;
if (!base64Image) {
  return { json: { ...orig, _aiError: 'Gemini returned no image' } };
}
return { json: { ...orig, _base64Image: base64Image } };

const imgbbResp = $input.item.json;
const orig = $('Extract Image Data').first().json;
const imageUrl = imgbbResp.data && imgbbResp.data.url ? imgbbResp.data.url : '';
if (!imageUrl) {
  return { json: { ...orig, imageUrl: '', _aiError: 'ImgBB upload failed' } };
}
return { json: { ...orig, imageUrl, _aiImageGenerated: true } };

const reg = $input.item.json;
const orig = $('Capture Image URL').first().json;
const uploadUrl = reg.value?.uploadMechanism?.['com.linkedin.digitalmedia.uploading.MediaUploadHttpRequest']?.uploadUrl;
const assetUrn = reg.value?.asset;
return [{ json: { ...orig, _liUploadUrl: uploadUrl, _liAssetUrn: assetUrn } }];

const d = $('Flatten User Credentials').first().json;
const raw = d.whatsappRecipients || '';
const numbers = raw.split(',').map(r => {
  let n = r.trim().replace(/^\+/, '').replace(/\s/g, '');
  // If number has no country code (10 digits starting with 6,7,8,9 = Indian number), prepend 91
  if (n.length === 10 && /^[6-9]/.test(n)) n = '91' + n;
  return n;
}).filter(r => r.length >= 10);
if (numbers.length === 0) return [{ json: { ...d, _waSkip: true } }];
return numbers.map(phone => ({ json: { ...d, waPhone: phone } }));

const d = $('Flatten User Credentials').first().json;
const tokenRes = $input.item.json;
const freshToken = tokenRes.access_token || d._gmail?.accessToken || '';
return { json: { ...d, _freshGmailToken: freshToken } };

const d = $input.item.json;
const allRecipients = (d.emailRecipients || d.contactEmail || '').split(',').map(r => r.trim()).filter(r => r && r.includes('@'));
if (allRecipients.length === 0) {
  const fallback = d.contactEmail || '';
  if (!fallback) return [{ json: { ...d, _emailSkip: true } }];
  return [{ json: { ...d, _recipientEmail: fallback } }];
}
return allRecipients.map(email => ({ json: { ...d, _recipientEmail: email } }));

const pagesResp = $input.item.json;
const pages = pagesResp.data || [];
if (pages.length === 0) throw new Error('No Facebook Pages found');
const page = pages[0];
const uid = $('FB Extract Params').first().json.uid;
return [{ json: { pageId: page.id, pageAccessToken: page.access_token, pageName: page.name, uid } }];

const igResp = $input.item.json;
const page = $('FB Extract Page').first().json;
return [{ json: { pageId: page.pageId, pageAccessToken: page.pageAccessToken, pageName: page.pageName, igId: igResp.instagram_business_account?.id || null, uid: page.uid } }];

const profile = $input.item.json;
const longToken = $('IG Get Long-lived Token').first().json;
return {
  json: {
    accessToken: longToken.access_token,
    userId: profile.id,
    username: profile.username || profile.name || ''
  }
};

const profile = $input.item.json;
const tokenNode = $('LI Exchange Code for Token').first().json;
return {
  json: {
    accessToken: tokenNode.access_token,
    name: profile.name || ((profile.given_name || '') + ' ' + (profile.family_name || '')).trim(),
    personUrn: 'urn:li:person:' + profile.sub,
    email: profile.email || ''
  }
};

const profile = $input.item.json;
const tokenData = $('Gmail Exchange Code').first().json;
return { json: { accessToken: tokenData.access_token, refreshToken: tokenData.refresh_token, email: profile.email || profile.name || '' } };

const tokenData = $('Eventbrite Exchange Code').first().json;
const orgData   = $input.item.json;
const uid       = $('Eventbrite Extract Params').first().json.uid;
const accessToken = tokenData.access_token || '';
const org = (orgData.organizations || [])[0] || {};
return { json: { accessToken, organizationId: org.id || '', organizationName: org.name || 'My Organization', uid } };

const userResp = $input.item.json;
const tokenData = $('TikTok Exchange Code').first().json;
const accessToken = tokenData.data?.access_token || tokenData.access_token || '';
const openId = tokenData.data?.open_id || tokenData.open_id || '';
const displayName = userResp.data?.user?.display_name || userResp.data?.user?.open_id || openId || 'TikTok User';
if (!accessToken) throw new Error('No access token in exchange response');
return { json: { accessToken, openId, displayName } };

const err = $input.item.json;
const msg = err.message || err.error_description || err.data?.description || JSON.stringify(err);
return { json: { error: true, message: msg } };

const body = $input.item.json.body || $input.item.json;
const creds = body.userCredentials || {};
const day = parseInt(body.day || 1);
const schedule = body.dailySchedule || [];
const dayContent = schedule[day - 1] || {};
return { json: {
  ...body,
  day,
  linkedinPost:     dayContent.linkedinPost     || body.linkedinPost     || '',
  instagramCaption: dayContent.instagramCaption  || body.instagramCaption || '',
  facebookPost:     dayContent.facebookPost      || body.facebookPost     || '',
  whatsappMessage:  dayContent.whatsappMessage   || body.whatsappMessage  || '',
  emailSubject:     dayContent.emailSubject      || body.emailSubject     || '',
  emailBody:        dayContent.emailBody         || body.emailBody        || '',
  imageUrl:         body.imageUrl                || '',
  platforms:        body.platforms               || 'linkedin,instagram,facebook,whatsapp,email',
  whatsappRecipients: body.whatsappRecipients    || '',
  emailRecipients:  body.emailRecipients         || body.contactEmail     || '',
  _fb:   creds.facebook  || null,
  _ig:   creds.instagram || null,
  _li:   creds.linkedin  || null,
  _gmail: creds.gmail    || null,
  timestamp: new Date().toISOString()
} };

const d = $('Day Normalize & Flatten').first().json;
const raw = d.whatsappRecipients || '';
const numbers = raw.split(',').map(r => {
  let n = r.trim().replace(/^\+/, '').replace(/\s/g, '');
  if (n.length === 10 && /^[6-9]/.test(n)) n = '91' + n;
  return n;
}).filter(r => r.length >= 10);
if (numbers.length === 0) return [{ json: { ...d, _waSkip: true } }];
return numbers.map(phone => ({ json: { ...d, waPhone: phone } }));

const d = $('Day Normalize & Flatten').first().json;
const allRecipients = (d.emailRecipients || d.contactEmail || '').split(',').map(r => r.trim()).filter(r => r && r.includes('@'));
if (allRecipients.length === 0) return [{ json: { ...d, _emailSkip: true } }];
return allRecipients.map(email => ({ json: { ...d, _recipientEmail: email } }));

const d = $input.item.json;
const body = d.body || d;
const agentType = body.agentType || 'seo';

const prompts = {
  reddit: `You are a Reddit marketing expert. Inputs:
- Subreddit(s): ${body.subreddit || ''}
- Topic: ${body.topic || ''}
- Brand Context: ${body.brandContext || ''}

Generate 3 authentic Reddit reply drafts that add genuine value and naturally reference the brand without being promotional. Also provide subreddit recommendations and an engagement strategy.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"Reddit Reply Drafts","sections":[{"heading":"Draft Reply 1","content":"..."},{"heading":"Draft Reply 2","content":"..."},{"heading":"Draft Reply 3","content":"..."},{"heading":"Best Subreddits to Target","content":"..."},{"heading":"Reddit Engagement Strategy","content":"..."}]}`,

  seo: `You are a senior SEO strategist. Inputs:
- Website: ${body.websiteUrl || ''}
- Target Keyword: ${body.targetKeyword || ''}
- Industry: ${body.industry || 'General'}

Generate a full SEO content package.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"SEO Content Package","sections":[{"heading":"Keyword Opportunities (15 keywords)","content":"..."},{"heading":"Full SEO Blog Post (800+ words)","content":"..."},{"heading":"Meta Tags & On-Page SEO","content":"..."},{"heading":"Featured Snippet Content","content":"..."},{"heading":"Internal Linking Strategy","content":"..."}]}`,

  writer: `You are a professional brand content writer. Inputs:
- Topic: ${body.topic || ''}
- Brand: ${body.brandName || ''}
- Audience: ${body.audience || ''}
- Tone: ${body.tone || 'Professional'}

Write a comprehensive long-form article.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"Long-Form Article","sections":[{"heading":"Full Article (1200+ words)","content":"..."},{"heading":"Social Media Snippets (5 quotes)","content":"..."},{"heading":"Email Newsletter Version (300 words)","content":"..."},{"heading":"Key Takeaways","content":"..."}]}`,

  twitter: `You are an X (Twitter) growth strategist. Inputs:
- Topic: ${body.topic || ''}
- Brand: ${body.brandName || ''}
- Tone: ${body.tone || 'Bold and engaging'}

Generate high-engagement Twitter/X content.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"X (Twitter) Content Drafts","sections":[{"heading":"Standalone Tweets (5)","content":"..."},{"heading":"Thread Draft (7 tweets)","content":"..."},{"heading":"Engagement Hook Tweets (3)","content":"..."},{"heading":"Hashtag Strategy","content":"..."}]}`,

  linkedin_agent: `You are a LinkedIn content strategist. Inputs:
- Topic: ${body.topic || ''}
- Brand/Person: ${body.brandName || ''}
- Audience: ${body.audience || 'B2B professionals'}

Generate LinkedIn content.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"LinkedIn Post Drafts","sections":[{"heading":"Post Draft 1 — Story Format","content":"..."},{"heading":"Post Draft 2 — Insight Format","content":"..."},{"heading":"Post Draft 3 — Engagement Format","content":"..."},{"heading":"Best Posting Schedule & Hashtags","content":"..."}]}`,

  hackernews: `You are a Hacker News community expert. Inputs:
- Topic: ${body.topic || ''}
- Brand/Product: ${body.brandName || ''}
- Value Proposition: ${body.value || ''}

Generate an HN engagement strategy.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"Hacker News Engagement Strategy","sections":[{"heading":"Show HN Post Draft","content":"..."},{"heading":"Comment Draft 1","content":"..."},{"heading":"Comment Draft 2","content":"..."},{"heading":"Comment Draft 3","content":"..."},{"heading":"Thread Targeting Strategy","content":"..."}]}`,

  geo: `You are a Generative Engine Optimization (GEO) expert specializing in getting brands cited in ChatGPT and Google AI Overviews. Inputs:
- Brand: ${body.brandName || ''}
- Keywords: ${body.keywords || ''}
- Description: ${body.description || ''}

Generate a complete GEO optimization package.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"GEO Optimization Package","sections":[{"heading":"AI Citation-Ready Content Blocks","content":"..."},{"heading":"Entity & Authority Building Strategy","content":"..."},{"heading":"FAQ Content for AI Overviews (10 Q&As)","content":"..."},{"heading":"Schema Markup Recommendations","content":"..."},{"heading":"Content Distribution Plan for AI Citations","content":"..."}]}`,

  coding: `You are a technical SEO engineer. Inputs:
- Website: ${body.websiteUrl || ''}
- Issue/Goal: ${body.issue || ''}
- Tech Stack: ${body.techStack || 'Unknown'}

Generate technical SEO fixes with code.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"Technical SEO Fix Plan","sections":[{"heading":"Diagnosis & Priority Issues","content":"..."},{"heading":"Code Fix 1 (Primary)","content":"..."},{"heading":"Code Fix 2 (Secondary)","content":"..."},{"heading":"Performance Optimizations","content":"..."},{"heading":"Testing & Verification Checklist","content":"..."}]}`,

  ugc_videos: `You are a UGC video content strategist. Inputs:
- Product/Service: ${body.product || ''}
- Style: ${body.style || ''}
- Audience: ${body.audience || 'General consumers'}
- Platforms: ${body.platforms || 'Instagram, TikTok'}

Generate UGC video briefs and scripts.

Respond ONLY with valid JSON (no markdown code fences, no extra text):
{"title":"UGC Video Brief & Scripts","sections":[{"heading":"Video Brief & Creative Direction","content":"..."},{"heading":"Full Script — Version 1 (60 seconds)","content":"..."},{"heading":"Short Script — Version 2 (30 seconds)","content":"..."},{"heading":"Hook Options (5 variations)","content":"..."},{"heading":"Platform Adaptations & Hashtags","content":"..."}]}`
};

const prompt = prompts[agentType] || prompts.seo;
return { json: { ...body, agentType, _agentPrompt: prompt } };

const geminiResp = $input.item.json;
const orig = $('Build Agent Prompt').first().json;

const rawText = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text || '';

if (!rawText) {
  return { json: { success: false, error: 'Gemini returned no content', agentResult: { title: 'Error', sections: [{ heading: 'Error', content: 'The AI agent did not return content. Please try again.' }] } } };
}

let agentResult;
try {
  let clean = rawText.trim();
  clean = clean.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  clean = clean.replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
  agentResult = JSON.parse(clean);
} catch (e) {
  agentResult = {
    title: orig.agentType + ' Results',
    sections: [{ heading: 'Generated Content', content: rawText }]
  };
}

return { json: { success: true, agentType: orig.agentType, agentResult } };
